{
  "metric": "trips",
  "target_window": "2024-11-28",
  "baseline_window": "2024-11-07, 2024-11-14, 2024-11-21",
  "hypotheses": [
    {
      "id": "H0",
      "kind": "metric",
      "statement": "Yellow taxi trips on Thursday 28 Nov 2024 dropped significantly compared to the average of the three prior Thursdays in November 2024.",
      "support_if": "Trips on 2024-11-28 are at least 20% lower than the mean trips on 2024-11-07, 2024-11-14, 2024-11-21.",
      "refute_if": "Trips on 2024-11-28 are within 5% of the baseline Thursday average."
    },
    {
      "id": "H1",
      "kind": "holiday",
      "statement": "Thanksgiving Day (2024-11-28) is a federal holiday that suppresses commuter and business travel, causing the trip drop.",
      "support_if": "whybot.us_holidays confirms 2024-11-28 is a federal holiday (Thanksgiving) and baseline Thursdays are not holidays.",
      "refute_if": "2024-11-28 is not listed as a holiday, or baseline Thursdays also show holiday flags."
    },
    {
      "id": "H2",
      "kind": "weather",
      "statement": "Adverse weather (precipitation, cold temperatures, or snow) on 2024-11-28 reduced demand relative to the baseline Thursdays.",
      "support_if": "nyc_weather_daily shows prcp_mm > 5 or snow_mm > 0 or tmax_c < 5 on 2024-11-28, while baseline Thursdays have milder conditions.",
      "refute_if": "Weather on 2024-11-28 is similar to or better than baseline Thursdays (dry, tmax_c > 10)."
    },
    {
      "id": "H3",
      "kind": "day_of_week",
      "statement": "The drop is partly explained by a general Thursday vs other weekdays pattern, but the specific Thursday 28 Nov is an outlier even for Thursdays.",
      "support_if": "Average Thursday trips in Nov 2024 (excluding 28th) are lower than Mon-Wed but 28 Nov is still a negative outlier vs those Thursdays.",
      "refute_if": "28 Nov trips are in line with the typical Thursday level for the month."
    },
    {
      "id": "H4",
      "kind": "fare_mix",
      "statement": "A shift in fare composition (e.g., fewer long-distance/airport trips, more short trips) on the holiday reduced trip counts if drivers stayed off the road.",
      "support_if": "avg_trip_distance on 2024-11-28 is materially lower than baseline Thursdays, indicating a mix shift toward shorter trips or supply withdrawal.",
      "refute_if": "avg_trip_distance and avg_total_amount on 2024-11-28 are similar to baseline Thursdays."
    },
    {
      "id": "H5",
      "kind": "data_quality",
      "statement": "The apparent drop is a data artifact: missing or delayed trip records for 2024-11-28 in the TLC feed.",
      "support_if": "Trip count is implausibly low (e.g., < 10k) and/or avg_total_amount / avg_trip_distance are NULL or extreme outliers.",
      "refute_if": "Trips, avg_total_amount, avg_trip_distance on 2024-11-28 are all populated and within plausible ranges."
    }
  ],
  "queries": [
    {
      "hypothesis_id": "H0",
      "purpose": "Get daily trips, avg_total_amount, avg_trip_distance for target date 2024-11-28 and baseline Thursdays 2024-11-07, 2024-11-14, 2024-11-21 from whybot.yellow_daily.",
      "tables": ["whybot.yellow_daily"]
    },
    {
      "hypothesis_id": "H1",
      "purpose": "Check whybot.us_holidays for holiday_name and is_national on 2024-11-28 and the three baseline Thursdays.",
      "tables": ["whybot.us_holidays"]
    },
    {
      "hypothesis_id": "H2",
      "purpose": "Retrieve prcp_mm, snow_mm, tmax_c, tmin_c for 2024-11-28 and the three baseline Thursdays from whybot.nyc_weather_daily.",
      "tables": ["whybot.nyc_weather_daily"]
    },
    {
      "hypothesis_id": "H3",
      "purpose": "Compute average trips for all Thursdays in November 2024 (2024-11-01 to 2024-11-30) from whybot.yellow_daily, and flag 2024-11-28 as outlier.",
      "tables": ["whybot.yellow_daily"]
    },
    {
      "hypothesis_id": "H4",
      "purpose": "Compare avg_trip_distance and avg_total_amount on 2024-11-28 vs baseline Thursdays from whybot.yellow_daily to detect fare/distance mix shift.",
      "tables": ["whybot.yellow_daily"]
    },
    {
      "hypothesis_id": "H5",
      "purpose": "Validate data quality for 2024-11-28: check trips > 0, avg_total_amount and avg_trip_distance not null, and values within historical min/max for November 2024.",
      "tables": ["whybot.yellow_daily"]
    }
  ],
  "rationale": "H0 quantifies the drop. H1 tests the Thanksgiving holiday effect (primary suspect). H2 checks weather (secondary). H3 contextualizes Thursday seasonality. H4 examines fare/distance mix as a proxy for trip-type composition. H5 rules out data gaps. All queries use only catalog tables and stay within the 2024-04-01..2025-02-28 window."
}

